USE SCHEMA DEMO_PARALLELS.RAW;

CREATE OR REPLACE TABLE RAW_SUBSCRIPTIONS (
    ID              INT AUTOINCREMENT,
    SUBSCRIPTION_ID VARCHAR,
    CUSTOMER_ID     VARCHAR,
    PRODUCT         VARCHAR,
    EVENT_TYPE      VARCHAR,
    AMOUNT          DECIMAL(10,2),
    CURRENCY        VARCHAR,
    EVENT_AT        TIMESTAMP,
    BODY            VARCHAR
);

